   291	/** Get the private pusher channel name for a Report. */
   292	function getReportChannelName(reportID: string): string {
   293	    return `${CONST.PUSHER.PRIVATE_REPORT_CHANNEL_PREFIX}${reportID}${CONFIG.PUSHER.SUFFIX}`;
